package app.fieldwatch.testing

import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Assume.assumeTrue
import org.junit.Rule
import org.junit.Test
import java.io.File

/**
 * P0-8d: release notes list every label and verdict change, generated by [ReleaseNotes].
 *
 * To write or refresh a release's block: `./gradlew testDebugUnitTest --tests '*ReleaseNotesTest*'
 * -PreleaseNotes=X.Y.Z -PreleaseFromCatalog=<last release's catalog version>`. The block goes into
 * `docs/release-notes/X.Y.Z.md` (which release.yml publishes), keeping the hand-written text around it.
 */
class ReleaseNotesTest {
    @get:Rule
    val golden = GoldenRule()

    private fun latest(): Int =
        TestFiles.repoFile("../catalog/snapshots").listFiles().orEmpty()
            .mapNotNull { Regex("""^v(\d+)\.json$""").matchEntire(it.name)?.groupValues?.get(1)?.toInt() }.max()

    /**
     * Everything that changed since Fieldwatch 1.1.32's catalog (v97), as the next release's notes would list it.
     * Each catalog PR re-blesses this golden, so its diff shows exactly the label and verdict changes that PR makes.
     */
    @Test
    fun changesSinceFieldwatch1132() {
        Golden.assertText("release/since-v97.md", ReleaseNotes.block(97, latest()))
    }

    /** Every committed notes file's catalog section is exactly what the frozen snapshots produce. */
    @Test
    fun committedNotesMatchTheirCatalogRange() {
        val dir = TestFiles.repoFile("../docs/release-notes")
        val notes = dir.listFiles().orEmpty().filter { it.name.endsWith(".md") }
        for (file in notes) {
            val text = file.readText(Charsets.UTF_8)
            val range = ReleaseNotes.declaredRange(text)
            assertTrue("${file.name} has no generated block (P0-8d)", range != null)
            val (from, to) = range!!
            assertEquals("${file.name}: its signature changes aren't the v$from → v$to diff", ReleaseNotes.signatures(from, to), ReleaseNotes.committedSignatures(text))
        }
    }

    /** Writes a release's block when asked (see the class doc); skipped otherwise. */
    @Test
    fun writeReleaseNotes() {
        val version = System.getProperty("spectre.releaseNotes").orEmpty()
        assumeTrue("Set -PreleaseNotes and -PreleaseFromCatalog to write release notes.", version.isNotBlank())
        val from = System.getProperty("spectre.releaseFromCatalog").orEmpty().toInt()
        val file: File = ReleaseNotes.write(version, from, latest())
        println("Release notes: wrote the generated block to ${file.name}")
    }
}
